glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
#if USE_ROUND
  uniform ROUND{
    float roundRadius;
    float roundRadiusRD;
    float roundRadiusLU;
    float roundRadiusLD;
  };
#endif
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  #endif
  #if USE_ROUND
    float value = roundRadius*0.01;
    float value1 = roundRadiusRD*0.01;
    float value2 = roundRadiusLU * 0.01;
    float value3 = roundRadiusLD * 0.01;
    vec2 rightUp = vec2(1.0-value,1.0-value);
    vec2 rightDown = vec2(1.0-value1,value1);
    vec2 leftUp = vec2(value2,1.0-value2);
    vec2 leftDown = vec2(value3,value3);
    if(((v_uv0.x>1.0-value&&v_uv0.y>1.0-value) && distance(v_uv0,rightUp)>value)
        ||((v_uv0.x>1.0-value1&&v_uv0.y<value1) && distance(v_uv0,rightDown)>value1)
        ||((v_uv0.x<value2&&v_uv0.y>1.0-value2) && distance(v_uv0,leftUp)>value2)
        ||((v_uv0.x<value3&&v_uv0.y<value3) && distance(v_uv0,leftDown)>value3)){
        o.a = 0.0;
    }
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  #if USE_BGRA
    gl_FragColor = o.bgra;
  #else
    gl_FragColor = o.rgba;
  #endif
}

